begin read only;
set local search_path='';set local timezone='UTC';set local lock_timeout='5s';set local statement_timeout='20s';
do $fixed533$begin if current_database()<>'postgres' or(select system_identifier::text from pg_control_system())<>'7701520506262638626'
 or(select count(*)from supabase_migrations.schema_migrations)<>29 or(select max(version)from supabase_migrations.schema_migrations)<>'20261030111549'
 then raise exception'RECONCILE533_EXACT_ORIGINAL29_REQUIRED';end if;end$fixed533$;
do $$declare r record;v text;result jsonb:='{}';begin for r in select n.nspname,c.relname from pg_class c join pg_namespace n on n.oid=c.relnamespace where c.relkind='r'and n.nspname in('eps','public','auth','storage','supabase_migrations','eps_local_guard')order by 1,2 loop execute format('select md5(coalesce(string_agg(to_jsonb(t)::text,E''\n''order by to_jsonb(t)::text),''''))from %I.%I t',r.nspname,r.relname)into v;result:=result||jsonb_build_object(r.nspname||'.'||r.relname,v);end loop;perform set_config('eps.m07.baseline_rows',result::text,true);end$$;select jsonb_build_object('table_rows',current_setting('eps.m07.baseline_rows')::jsonb,'functions',(select md5(string_agg(pg_get_functiondef(p.oid),E'\n'order by p.oid::regprocedure::text))from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in('eps','public')and p.prokind='f'),'grants',(select md5(string_agg(c.oid::text||coalesce(c.relacl::text,''),E'\n'order by c.oid))from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in('eps','public','auth','storage')));
select jsonb_build_object('roles',(select jsonb_agg(jsonb_build_object('oid',oid,'name',rolname,'login',rolcanlogin,'superuser',rolsuper,'inherit',rolinherit,'bypassrls',rolbypassrls,'replication',rolreplication,'create_role',rolcreaterole,'create_db',rolcreatedb,'connection_limit',rolconnlimit,'valid_until',rolvaliduntil)order by rolname)from pg_roles),'memberships',(select jsonb_agg(jsonb_build_object('role_oid',roleid,'member_oid',member,'grantor_oid',grantor,'admin',admin_option,'inherit',inherit_option,'set',set_option)order by roleid,member,grantor)from pg_auth_members));
-- Metadata only. No source bodies, Auth identities, credentials or business rows.
-- Caller fixes search_path and owns the transaction. Object keys exclude OIDs.
with nested as(select jsonb_build_object(
 'functions',(select coalesce(jsonb_object_agg(signature,metadata),'{}')from(
  select p.oid::regprocedure::text signature,jsonb_build_object('owner',p.proowner::regrole::text,'language',(select lanname from pg_language where oid=p.prolang),'returns',pg_get_function_result(p.oid),'identity_arguments',pg_get_function_identity_arguments(p.oid),'argument_defaults',pg_get_expr(p.proargdefaults,0),'strict',p.proisstrict,'parallel',p.proparallel,'leakproof',p.proleakproof,'kind',p.prokind,'support',case when p.prosupport=0 then null else p.prosupport::regproc::text end,'definer',p.prosecdef,'volatility',p.provolatile,'config',p.proconfig,'acl',p.proacl::text,'source_sha256',encode(sha256(convert_to(replace(p.prosrc,E'\r\n',E'\n'),'UTF8')),'hex'))metadata
  from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in('eps','public','auth','storage'))s),
 'tables',(select coalesce(jsonb_object_agg(name,metadata),'{}')from(
  select n.nspname||'.'||c.relname name,jsonb_build_object('owner',c.relowner::regrole::text,'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,'acl',c.relacl::text)metadata
  from pg_class c join pg_namespace n on n.oid=c.relnamespace where(n.nspname in('eps','public','auth','storage'))and c.relkind='r')s),
 'columns',(select coalesce(jsonb_object_agg(n.nspname||'.'||c.relname||'.'||a.attname,jsonb_build_object('type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull,'acl',a.attacl::text,'identity',a.attidentity,'generated',a.attgenerated,'default',pg_get_expr(d.adbin,d.adrelid))),'{}')from pg_attribute a join pg_class c on c.oid=a.attrelid join pg_namespace n on n.oid=c.relnamespace left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum where(n.nspname in('eps','public','auth','storage'))and c.relkind='r'and a.attnum>0 and not a.attisdropped),
 'policies',(select coalesce(jsonb_object_agg(schemaname||'.'||tablename||'.'||policyname,to_jsonb(p)-'schemaname'-'tablename'-'policyname'),'{}')from pg_policies p where schemaname in('eps','public','auth','storage')),
 'constraints',(select coalesce(jsonb_object_agg(n.nspname||'.'||c.relname||'.'||k.conname,jsonb_build_object('definition',replace(pg_get_constraintdef(k.oid),E'\r\n',E'\n'))),'{}')from pg_constraint k join pg_class c on c.oid=k.conrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname in('eps','public','auth','storage')),
 'indexes',(select coalesce(jsonb_object_agg(n.nspname||'.'||c.relname,jsonb_build_object('definition',replace(pg_get_indexdef(c.oid),E'\r\n',E'\n'),'valid',i.indisvalid,'ready',i.indisready,'live',i.indislive)),'{}')from pg_index i join pg_class c on c.oid=i.indexrelid join pg_namespace n on n.oid=c.relnamespace join pg_class t on t.oid=i.indrelid where n.nspname in('eps','public','auth','storage')),
 'triggers',(select coalesce(jsonb_object_agg(n.nspname||'.'||c.relname||'.'||t.tgname,jsonb_build_object('definition',pg_get_triggerdef(t.oid),'enabled',t.tgenabled)),'{}')from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where(n.nspname in('eps','public','auth','storage'))and not t.tgisinternal),
 'schemas',(select coalesce(jsonb_object_agg(nspname,jsonb_build_object('owner',nspowner::regrole::text,'acl',nspacl::text)),'{}')from pg_namespace where nspname in('eps','public','storage','auth','extensions')),
 'types',(select coalesce(jsonb_object_agg(n.nspname||'.'||t.typname,jsonb_build_object('owner',t.typowner::regrole::text,'kind',t.typtype,'acl',t.typacl::text,'base',case when t.typbasetype=0 then null else format_type(t.typbasetype,t.typtypmod)end,'not_null',t.typnotnull,'default',t.typdefault,'enum_labels',(select jsonb_agg(enumlabel order by enumsortorder)from pg_enum where enumtypid=t.oid))),'{}')from pg_type t join pg_namespace n on n.oid=t.typnamespace where n.nspname in('eps','public','auth','storage')and t.typelem=0),
 'default_acl',(select coalesce(jsonb_object_agg(d.defaclrole::regrole::text||'/'||coalesce(n.nspname,'*')||'/'||d.defaclobjtype::text,jsonb_build_object('acl',d.defaclacl::text)),'{}')from pg_default_acl d left join pg_namespace n on n.oid=d.defaclnamespace where n.nspname in('eps','public','storage','auth','extensions')or d.defaclrole::regrole::text like'eps_%'),
 'roles',(select coalesce(jsonb_object_agg(rolname,jsonb_build_object('login',rolcanlogin,'super',rolsuper,'inherit',rolinherit,'bypassrls',rolbypassrls,'create_role',rolcreaterole,'create_db',rolcreatedb,'replication',rolreplication,'connection_limit',rolconnlimit,'valid_until',rolvaliduntil)),'{}')from pg_roles where rolname like'eps_%'),
 'memberships',(select coalesce(jsonb_object_agg(roleid::regrole::text||'>'||member::regrole::text||'/'||grantor::regrole::text,jsonb_build_object('grantor',grantor::regrole::text,'admin',admin_option,'inherit',inherit_option,'set',set_option)),'{}')from pg_auth_members where roleid::regrole::text like'eps_%'or member::regrole::text like'eps_%')
)payload),flat as(select category.key||'|'||object.key||'|'||field.key key,field.value from nested cross join lateral jsonb_each(payload)category cross join lateral jsonb_each(category.value)object cross join lateral jsonb_each(object.value)field)
select coalesce(jsonb_object_agg(key,value),'{}')catalog from flat;

select jsonb_build_object('scope','fixed533_read_only_reconciliation','run_id','5332c86b-b1f9-410e-8702-647031182b17',
 'target_roles',(select coalesce(jsonb_agg(jsonb_build_object('name',r.rolname,'oid',r.oid,'marker_matches',shobj_description(r.oid,'pg_authid')=case r.rolname when 'eps_mcp_issuer_owner'then 'eps-m07-recovery33:5332c86b-b1f9-410e-8702-647031182b17:issuer'else 'eps-m07-recovery33:5332c86b-b1f9-410e-8702-647031182b17:consent'end,
 'marker',case when shobj_description(r.oid,'pg_authid')=case r.rolname when 'eps_mcp_issuer_owner'then 'eps-m07-recovery33:5332c86b-b1f9-410e-8702-647031182b17:issuer'else 'eps-m07-recovery33:5332c86b-b1f9-410e-8702-647031182b17:consent'end then case r.rolname when 'eps_mcp_issuer_owner'then 'eps-m07-recovery33:5332c86b-b1f9-410e-8702-647031182b17:issuer'else 'eps-m07-recovery33:5332c86b-b1f9-410e-8702-647031182b17:consent'end else null end,
 'login',r.rolcanlogin,'super',r.rolsuper,'inherit',r.rolinherit,'bypassrls',r.rolbypassrls,'create_role',r.rolcreaterole,'create_db',r.rolcreatedb,'replication',r.rolreplication,'connection_limit',r.rolconnlimit,'valid_until',r.rolvaliduntil,
 'memberships',(select coalesce(jsonb_agg(jsonb_build_object('role_oid',roleid,'member_oid',member,'grantor_oid',grantor,'admin',admin_option,'inherit',inherit_option,'set',set_option)order by roleid,member,grantor),'[]')from pg_auth_members where roleid=r.oid or member=r.oid or grantor=r.oid),
 'dependencies',(select coalesce(jsonb_agg(jsonb_build_object('dbid',dbid,'classid',classid,'objid',objid,'objsubid',objsubid,'deptype',deptype)order by dbid,classid,objid,objsubid),'[]')from pg_shdepend where refclassid='pg_authid'::regclass and refobjid=r.oid))order by r.rolname),'[]')from pg_roles r where r.rolname in('eps_mcp_issuer_owner','eps_oauth_consent_owner')),
 'database_exists',jsonb_build_object('eps_m07_r33_source_5332c86bb1f9410e8702647031182b17',exists(select 1 from pg_database where datname='eps_m07_r33_source_5332c86bb1f9410e8702647031182b17'),'eps_m07_r33_restore_5332c86bb1f9410e8702647031182b17',exists(select 1 from pg_database where datname='eps_m07_r33_restore_5332c86bb1f9410e8702647031182b17')),
 'other_clients',(select count(*)from pg_stat_activity where backend_type='client backend'and pid<>pg_backend_pid()),
 'client_pids',(select coalesce(jsonb_agg(pid order by pid),'[]')from pg_stat_activity where backend_type='client backend'and pid<>pg_backend_pid()));
rollback;
